from copy import deepcopy
from corpus_cases import *

def custom_field(label,reps,kind='F',copies=1,reality=None):
    f=field(label,kind=kind,copies=copies,reality=reality)
    f['gauge_representations']=reps
    return f

def weight(a):return {'dynkin':a}
def charge(q):return {'charge':str(q)}
def spectrum(pid,name,factors,fields):
    return {'schema_version':'field-content-1','inventory_complete':True,'paper_ids':[pid],'name':name,'gauge_factors':factors,'matter':fields}

factors331=[{'id':'colour','family':'A','rank':2},{'id':'left','family':'A','rank':2},{'id':'n','family':'U1','rank':1}]
def f331(label,c,l,n,kind='F',copies=1):return custom_field(label,{'colour':weight(c),'left':weight(l),'n':charge(n)},kind,copies)
pp=spectrum('P16','Pisano-Pleitez displayed three-triplet model',factors331,[f331('lepton triplets',[0,0],[1,0],'0',copies=3),f331('Q1_L',[1,0],[1,0],'2/3'),f331('Q23_L',[1,0],[0,1],'-1/3',copies=2),f331('u_R',[1,0],[0,0],'2/3','R',3),f331('d_R',[1,0],[0,0],'-1/3','R',3),f331('J1_R',[1,0],[0,0],'5/3','R'),f331('J23_R',[1,0],[0,0],'-4/3','R',2),f331('eta',[0,0],[1,0],'0','S'),f331('rho',[0,0],[1,0],'1','S'),f331('chi',[0,0],[1,0],'-1','S')])
pp_extra=deepcopy(pp);pp_extra['name']='Pisano-Pleitez with sigma and omega';pp_extra['matter'] += [f331('sigma,omega',[0,0],[1,0],'0','S',2)]
record('P16',[claim('P16','331','Section II Eqs.(3)-(10)','We start by choosing','One first-family quark SU(3)L triplet with N=2/3, two anti-triplets with N=-1/3, three lepton triplets N=0 containing charged antileptons; no RH neutrinos. RH quarks are SU(3)L singlets, usual u/d N=2/3,-1/3, exotic J1=5/3 and two J=-4/3. Explicit colour counted for anomalies. Scalars eta,rho,chi are complex SU(3)L triplets of N=0,+1,-1. Normalize whole spectrum by q=3N; conjugate every RH colour and charge.'),claim('P16','extra','Section III after Eq.(40)','two new Higgs triplets','Optional sigma and omega have exactly eta quantum numbers; add two complex triplets (1,3,0), not a new arbitrary charge family.')],
 'Complete displayed fermion/scalar definition and explicitly specified sigma/omega extension.',candidates=[candidate('331',pp,'pp331-displayed',['331']),candidate('331-extra',pp_extra,'pp331-sigma-omega',['331','extra'])],status='completed_scoped_reextraction_staged')

qlf=[{'id':'colour4','family':'A','rank':3},{'id':'weak','family':'A','rank':1},{'id':'r','family':'U1','rank':1}]
def qlfield(label,c,w,q,kind='F',copies=1):return custom_field(label,{'colour4':weight(c),'weak':weight([w]),'r':charge(q)},kind,copies)
